'use client';
import React, { useState } from 'react';
import { 
  Eye, 
  CheckCircle, 
  XCircle, 
  Ban, 
  MoreVertical,
  User,
  Mail,
  Calendar,
  AlertTriangle
} from 'lucide-react';
import { API_URL } from '../api/apiURL';

const ReportedContent = ({ 
  report, 
  currentPage, 
  totalPages, 
  setCurrentPage, 
  itemsPerPage,
  refreshReports,
  onDataUpdate,
  loading
}) => {
  const [actionLoading, setActionLoading] = useState({});
  const [selectedReport, setSelectedReport] = useState(null);
  const [showDetails, setShowDetails] = useState(false);

  // ✅ Format date
  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    return new Date(dateString).toLocaleDateString('en-IN', {
      day: '2-digit',
      month: 'short',
      year: 'numeric'
    });
  };

  // ✅ Get status badge style
  const getStatusBadge = (status) => {
    const statusLower = status?.toLowerCase();
    switch (statusLower) {
      case 'pending':
        return { bg: 'bg-yellow-100', text: 'text-yellow-800', label: 'Pending' };
      case 'reviewed':
        return { bg: 'bg-blue-100', text: 'text-blue-800', label: 'Reviewed' };
      case 'approved':
        return { bg: 'bg-green-100', text: 'text-green-800', label: 'Approved' };
      case 'blocked':
        return { bg: 'bg-red-100', text: 'text-red-800', label: 'Blocked' };
      default:
        return { bg: 'bg-gray-100', text: 'text-gray-800', label: status || 'Unknown' };
    }
  };

  // ✅ Handle view details
  const handleViewDetails = (report) => {
    setSelectedReport(report);
    setShowDetails(true);
  };

  // ✅ Handle status update
  const handleStatusUpdate = async (reportId, newStatus) => {
    if (!window.confirm(`Are you sure you want to mark this as ${newStatus}?`)) return;
    
    setActionLoading(prev => ({ ...prev, [reportId]: true }));
    
    try {
      const response = await fetch(`${API_URL}/admin/update-report-status`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          reportId, 
          status: newStatus,
          updatedAt: new Date().toISOString()
        }),
      });

      const result = await response.json();
      
      if (response.ok) {
        // ✅ OPTION 1: Optimistic Update
        // const updatedReports = report.map(r => 
        //   r._id === reportId ? { ...r, status: newStatus } : r
        // );
        // onReportsUpdate(updatedReports);
        
        // ✅ OPTION 2: Refresh from server (Recommended)
        if (refreshReports) {
          refreshReports();
        }
        if (onDataUpdate) {
          onDataUpdate();
        }
        
        // Show success message
        alert(`Report marked as ${newStatus} successfully!`);
      } else {
        throw new Error(result.message || 'Failed to update status');
      }
    } catch (error) {
      console.error('Error updating status:', error);
      alert(`Error: ${error.message}`);
    } finally {
      setActionLoading(prev => ({ ...prev, [reportId]: false }));
    }
  };

  // ✅ Handle block user
  const handleBlockUser = async (userId, userName) => {
    if (!window.confirm(`Are you sure you want to block ${userName || 'this user'}?`)) return;
    
    try {
      console.log('🚫 Blocking user:', userId);
      
      const response = await fetch(`${API_URL}/admin/block-user`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          userId,
          reason: 'Reported by admin',
          blockedAt: new Date().toISOString()
        }),
      });

      const result = await response.json();
      
      if (response.ok) {
        console.log('✅ User blocked successfully:', result);
        
        // ✅ TRIGGER DATA REFRESH - यहाँ fix है
        if (refreshReports) {
          console.log('🔄 Calling refreshReports from parent');
          refreshReports();
        }
        
        if (onDataUpdate) {
          console.log('🔄 Calling onDataUpdate callback');
          onDataUpdate();
        }
        
        // ✅ Also update local status if needed
        // const updatedReports = report.map(r => 
        //   r.userId === userId ? { ...r, status: 'blocked' } : r
        // );
        // onReportsUpdate(updatedReports);
        
        alert(`User ${userName || ''} has been blocked successfully!`);
      } else {
        throw new Error(result.message || 'Failed to block user');
      }
    } catch (error) {
      console.error('❌ Error blocking user:', error);
      alert(`Error: ${error.message}`);
    }
  };

  // ✅ Pagination
  const handlePageChange = (page) => {
    if (page >= 1 && page <= totalPages) {
      setCurrentPage(page);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  // ✅ Calculate pagination range
  const getPaginationRange = () => {
    const delta = 2;
    const range = [];
    const rangeWithDots = [];

    for (let i = 1; i <= totalPages; i++) {
      if (
        i === 1 ||
        i === totalPages ||
        (i >= currentPage - delta && i <= currentPage + delta)
      ) {
        range.push(i);
      }
    }

    let prev = 0;
    for (const i of range) {
      if (i - prev > 1) {
        rangeWithDots.push('...');
      }
      rangeWithDots.push(i);
      prev = i;
    }

    return rangeWithDots;
  };

  return (
    <>
      {/* TABLE CONTAINER */}
      <div className="overflow-x-auto rounded-lg border border-gray-300">
        <table className="min-w-full divide-y divide-gray-300">
          <thead className="bg-gray-100">
            <tr>
              <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                Reported User
              </th>
              <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                Details
              </th>
              <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                Status
              </th>
              <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                Date
              </th>
              <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                Actions
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {report.map((item) => {
              const statusBadge = getStatusBadge(item.status);
              return (
                <tr 
                  key={item._id || item.id} 
                  className="hover:bg-gray-50 transition-colors"
                >
                  {/* USER INFO */}
                  <td className="px-4 py-4">
                    <div className="flex items-center">
                      <div className="flex-shrink-0 h-10 w-10 bg-blue-100 rounded-full flex items-center justify-center">
                        <User className="h-6 w-6 text-blue-600" />
                      </div>
                      <div className="ml-4">
                        <div className="text-sm font-medium text-gray-900">
                          {item.reportedUserName || 'Unknown User'}
                        </div>
                        <div className="text-sm text-gray-500 flex items-center gap-1">
                          <Mail className="w-3 h-3" />
                          {item.reportedUserEmail || 'No email'}
                        </div>
                        <div className="text-xs text-gray-400 mt-1">
                          ID: {item.userId?.substring(0, 8)}...
                        </div>
                      </div>
                    </div>
                  </td>

                  {/* REPORT DETAILS */}
                  <td className="px-4 py-4">
                    <div className="max-w-xs">
                      <div className="text-sm text-gray-900 font-medium">
                        {item.reportType || 'General Report'}
                      </div>
                      <div className="text-sm text-gray-500 truncate">
                        {item.reportDescription || 'No description provided'}
                      </div>
                      <button
                        onClick={() => handleViewDetails(item)}
                        className="text-xs text-blue-600 hover:text-blue-800 mt-1 flex items-center gap-1"
                      >
                        <Eye className="w-3 h-3" />
                        View details
                      </button>
                    </div>
                  </td>

                  {/* STATUS */}
                  <td className="px-4 py-4">
                    <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium ${statusBadge.bg} ${statusBadge.text}`}>
                      {statusBadge.label}
                    </span>
                  </td>

                  {/* DATE */}
                  <td className="px-4 py-4 whitespace-nowrap">
                    <div className="text-sm text-gray-900">
                      {formatDate(item.createdAt)}
                    </div>
                    <div className="text-xs text-gray-500 flex items-center gap-1">
                      <Calendar className="w-3 h-3" />
                      {item.createdAt ? new Date(item.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : 'N/A'}
                    </div>
                  </td>

                  {/* ACTIONS */}
                  <td className="px-4 py-4">
                    <div className="flex items-center gap-2">
                      {/* Mark as Reviewed */}
                      <button
                        onClick={() => handleStatusUpdate(item._id || item.id, 'reviewed')}
                        disabled={actionLoading[item._id] || item.status === 'reviewed'}
                        className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed"
                        title="Mark as Reviewed"
                      >
                        <Eye className="w-4 h-4" />
                      </button>

                      {/* Approve */}
                      <button
                        onClick={() => handleStatusUpdate(item._id || item.id, 'approved')}
                        disabled={actionLoading[item._id] || item.status === 'approved'}
                        className="p-2 text-green-600 hover:bg-green-50 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed"
                        title="Approve Report"
                      >
                        <CheckCircle className="w-4 h-4" />
                      </button>

                      {/* Block User */}
                      <button
                        onClick={() => handleBlockUser(item.userId, item.reportedUserName)}
                        disabled={actionLoading[item.userId] || item.status === 'blocked'}
                        className="p-2 text-red-600 hover:bg-red-50 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed"
                        title="Block User"
                      >
                        <Ban className="w-4 h-4" />
                      </button>

                      {/* More Options */}
                      <div className="relative">
                        <button className="p-2 text-gray-600 hover:bg-gray-100 rounded-lg">
                          <MoreVertical className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* PAGINATION */}
      {totalPages > 1 && (
        <div className="flex flex-col sm:flex-row items-center justify-between px-4 py-4 border-t border-gray-300">
          <div className="text-sm text-gray-700 mb-4 sm:mb-0">
            Showing <span className="font-medium">{(currentPage - 1) * itemsPerPage + 1}</span> to{' '}
            <span className="font-medium">{Math.min(currentPage * itemsPerPage, report.length)}</span> of{' '}
            <span className="font-medium">{report.length}</span> results
          </div>
          
          <div className="flex items-center gap-1">
            {/* Previous Button */}
            <button
              onClick={() => handlePageChange(currentPage - 1)}
              disabled={currentPage === 1 || loading}
              className="px-3 py-2 border border-gray-300 rounded-md text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Previous
            </button>
            
            {/* Page Numbers */}
            {getPaginationRange().map((pageNum, index) => (
              pageNum === '...' ? (
                <span key={`dots-${index}`} className="px-3 py-2 text-gray-500">
                  ...
                </span>
              ) : (
                <button
                  key={pageNum}
                  onClick={() => handlePageChange(pageNum)}
                  disabled={loading}
                  className={`px-3 py-2 border rounded-md text-sm font-medium ${
                    currentPage === pageNum
                      ? 'bg-blue-600 text-white border-blue-600'
                      : 'border-gray-300 text-gray-700 hover:bg-gray-50'
                  } disabled:opacity-50 disabled:cursor-not-allowed`}
                >
                  {pageNum}
                </button>
              )
            ))}
            
            {/* Next Button */}
            <button
              onClick={() => handlePageChange(currentPage + 1)}
              disabled={currentPage === totalPages || loading}
              className="px-3 py-2 border border-gray-300 rounded-md text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Next
            </button>
          </div>
        </div>
      )}

      {/* DETAILS MODAL */}
      {showDetails && selectedReport && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <h3 className="text-xl font-bold text-gray-900">Report Details</h3>
                  <p className="text-gray-600">ID: {selectedReport._id}</p>
                </div>
                <button
                  onClick={() => setShowDetails(false)}
                  className="text-gray-400 hover:text-gray-600"
                >
                  ✕
                </button>
              </div>
              
              <div className="space-y-6">
                {/* User Info */}
                <div className="bg-gray-50 p-4 rounded-lg">
                  <h4 className="font-semibold text-gray-800 mb-3">Reported User</h4>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <p className="text-sm text-gray-600">Name</p>
                      <p className="font-medium">{selectedReport.reportedUserName || 'N/A'}</p>
                    </div>
                    <div>
                      <p className="text-sm text-gray-600">Email</p>
                      <p className="font-medium">{selectedReport.reportedUserEmail || 'N/A'}</p>
                    </div>
                    <div>
                      <p className="text-sm text-gray-600">User ID</p>
                      <p className="font-medium text-sm font-mono">{selectedReport.userId || 'N/A'}</p>
                    </div>
                    <div>
                      <p className="text-sm text-gray-600">Gender</p>
                      <p className="font-medium">{selectedReport.gender || 'N/A'}</p>
                    </div>
                  </div>
                </div>

                {/* Report Details */}
                <div>
                  <h4 className="font-semibold text-gray-800 mb-3">Report Information</h4>
                  <div className="space-y-3">
                    <div>
                      <p className="text-sm text-gray-600">Report Type</p>
                      <p className="font-medium">{selectedReport.reportType || 'General'}</p>
                    </div>
                    <div>
                      <p className="text-sm text-gray-600">Description</p>
                      <p className="font-medium mt-1 p-3 bg-gray-50 rounded-lg">
                        {selectedReport.reportDescription || 'No description provided'}
                      </p>
                    </div>
                    <div>
                      <p className="text-sm text-gray-600">Reporter Info</p>
                      <p className="font-medium">{selectedReport.reporterName || 'Anonymous'}</p>
                    </div>
                  </div>
                </div>

                {/* Timeline */}
                <div>
                  <h4 className="font-semibold text-gray-800 mb-3">Timeline</h4>
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span className="text-sm text-gray-600">Created</span>
                      <span className="font-medium">{formatDate(selectedReport.createdAt)}</span>
                    </div>
                    {selectedReport.updatedAt && (
                      <div className="flex justify-between">
                        <span className="text-sm text-gray-600">Last Updated</span>
                        <span className="font-medium">{formatDate(selectedReport.updatedAt)}</span>
                      </div>
                    )}
                  </div>
                </div>

                {/* Current Status */}
                <div>
                  <h4 className="font-semibold text-gray-800 mb-3">Current Status</h4>
                  <div className="flex items-center gap-3">
                    <span className={`px-3 py-1 rounded-full text-sm font-medium ${getStatusBadge(selectedReport.status).bg} ${getStatusBadge(selectedReport.status).text}`}>
                      {getStatusBadge(selectedReport.status).label}
                    </span>
                    <span className="text-sm text-gray-600">
                      Last action by: {selectedReport.actionBy || 'System'}
                    </span>
                  </div>
                </div>
              </div>

              {/* Action Buttons */}
              <div className="flex justify-end gap-3 mt-8 pt-6 border-t">
                <button
                  onClick={() => setShowDetails(false)}
                  className="px-5 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                >
                  Close
                </button>
                <button
                  onClick={() => {
                    if (window.confirm('Are you sure you want to block this user?')) {
                      handleBlockUser(selectedReport.userId, selectedReport.reportedUserName);
                      setShowDetails(false);
                    }
                  }}
                  className="px-5 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 flex items-center gap-2"
                >
                  <Ban className="w-4 h-4" />
                  Block User
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default ReportedContent;